INSERT INTO `templates` VALUES (1,'E-Mail Vorlage für Reservierungen','<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Sehr geehrte/r <span class=\"mceNonEditable\">[[reservation1.booker.salutation]] <span class=\"mceNonEditable\">[[reservation1.booker.lastname]]</span></span>,</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">wir bedanken uns für Ihre Buchung. Im Anhang erhalten Sie die Zimmerreservierungsbestätigung mit <strong>allen wichtigen Informationen</strong>.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Mit freundlichen Grüßen</span></p>\n</body>\n</html>','{\"orientation\": \"P\", \"marginLeft\": 25, \"marginRight\": 20, \"marginTop\": 20, \"marginBottom\": 20, \"marginHeader\": 9, \"marginFooter\": 9}',1,NULL,NULL),(2,'PDF Rechnung','<style>\r\ntable {\r\n  border-spacing: 0;\r\n  border-collapse: collapse; \r\n}\r\ntable th,td {\r\n  padding-right: 5px;\r\n  padding-left: 5px;\r\n}\r\n</style>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18pt; font-family: arial, helvetica, sans-serif;\"><strong>Unterkunft zum sonnigen Gemüt</strong></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><span style=\"font-size: 10pt;\">Inhaber: Max Mustermann<br></span><span style=\"font-size: 10pt;\">Musterstraße 12, </span><span style=\"font-size: 10pt;\">12345 Musterhause</span></span><br><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">Telefon: 123456 789, Mobil: 987654321</span></p>\r\n<p><span style=\"font-size: 16pt; font-family: arial, helvetica, sans-serif;\"><strong>Rechnung</strong></span></p>\r\n<p><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[invoice.firstname]]</span> <span class=\"mceNonEditable\">[[invoice.lastname]]</span><br><span class=\"mceNonEditable\">[[invoice.company]]</span><br><span class=\"mceNonEditable\">[[invoice.address]]</span><br><span class=\"mceNonEditable\">[[invoice.zip]]</span> <span class=\"mceNonEditable\">[[invoice.city]]</span><br></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><strong>Rechnungsnr.</strong><br><span class=\"mceNonEditable\">[[invoice.number]]</span><br><strong>Rechnungsdatum</strong><br><span class=\"mceNonEditable\">[[invoice.date|date(\'d.m.Y\')]]</span><br></span></p>\r\n<p style=\"text-align: left;\"> </p>\r\n<table style=\"width: 100%;\">\r\n<thead>\r\n<tr style=\"background-color: #ced4d9;\">\r\n<th style=\"border-bottom: 1px solid #333333; text-align: left;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Zimmer</span></th>\r\n<th style=\"border-bottom: 1px solid #333333; text-align: center;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Anzahl</span></th>\r\n<th style=\"text-align: right; border-bottom: 1px solid #333333;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Einzelpreis</span></th>\r\n<th style=\"text-align: right; border-bottom: 1px solid #333333;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">MwSt.</span></th>\r\n<th style=\"text-align: right; border-bottom: 1px solid #333333;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Gesamt</span></th>\r\n</tr>\r\n</thead>\r\n<tbody><!-- [% for appartment in invoice.appartments %] -->\r\n<tr>\r\n<td style=\"border-bottom: 1px solid #DDDDDD;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[appartement.description]]</span> (Personen: <span class=\"mceNonEditable\">[[appartement.persons]]</span>)</span><br><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[appartement.startDate|date(\'d.m.Y\')]]</span> - <span class=\"mceNonEditable\">[[appartement.endDate|date(\'d.m.Y\')]]</span></span></td>\r\n<td style=\"text-align: center; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">[[appartement.amount]]</span></td>\r\n<td style=\"text-align: right; border-bottom: 1px solid #DDDDDD;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[appartement.priceFormated]]</span> €</span></td>\r\n<td style=\"text-align: right; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">[[appartement.vat]]</span></td>\r\n<td style=\"text-align: right; border-bottom: 1px solid #DDDDDD;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[appartement.totalPrice]]</span> €</span></td>\r\n</tr>\r\n<!-- [% endfor %] -->\r\n<tr>\r\n<td style=\"text-align: right;\" colspan=\"5\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\"><strong>[[appartementTotal]]</strong></span><strong> €</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"text-align: left;\"> </p>\r\n<table style=\"width: 100%;\">\r\n<thead>\r\n<tr style=\"background-color: #ced4d9;\">\r\n<th style=\"border-bottom: 1px solid #333333; text-align: left;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">weitere Leistungen</span></th>\r\n<th style=\"border-bottom: 1px solid #333333; text-align: center;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Anzahl</span></th>\r\n<th style=\"text-align: right; border-bottom: 1px solid #333333;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Einzelpreis</span></th>\r\n<th style=\"text-align: right; #dddddd; border-bottom: 1px solid #333333;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">MwSt.</span></th>\r\n<th style=\"text-align: right; border-bottom: 1px solid #333333;\" scope=\"col\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Gesamt</span></th>\r\n</tr>\r\n</thead>\r\n<tbody><!-- [% for position in invoice.positions %] -->\r\n<tr style=\"border-bottom: 1px solid #DDDDDD;\">\r\n<td style=\"border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">[[position.description]]</span></td>\r\n<td style=\"border-bottom: 1px solid #dddddd; text-align: center;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">[[position.amount]]</span></td>\r\n<td style=\"text-align: right; border-bottom: 1px solid #DDDDDD;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[position.priceFormated]]</span> €</span></td>\r\n<td style=\"text-align: right; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">[[position.vat]]</span></td>\r\n<td style=\"text-align: right; border-bottom: 1px solid #DDDDDD;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[position.totalPrice]]</span> €</span></td>\r\n</tr>\r\n<!-- [% endfor %] -->\r\n<tr>\r\n<td style=\"text-align: right;\" colspan=\"5\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\"><strong>[[miscTotal]]</strong></span><strong> €</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p> </p>\r\n<table style=\"width: 100%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 33.3333%;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">enthaltene Mehrwertsteuer</span><br>\r\n<table border=\"0\"><!-- [% for key, value in vats %] -->\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: right;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">[[key]] %:</span></td>\r\n<td style=\"text-align: right;\"><span class=\"mceNonEditable\" style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"> [[value.nettoFormated]] €</span></td>\r\n</tr>\r\n<!-- [% endfor %] --></tbody>\r\n</table>\r\n<span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><br></span></td>\r\n<td style=\"width: 47.7411%; text-align: right; vertical-align: top;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">Netto</span><br><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><strong>Brutto</strong></span></td>\r\n<td style=\"width: 18.9255%; text-align: right; vertical-align: top;\"><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[nettoFormated]] </span>€</span><br><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><strong><span class=\"mceNonEditable\">[[bruttoFormated]] </span>€</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Das Datum der Rechnung entspricht dem Leistungsdatum.</span></p>\r\n<p><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\">Zahlbar nach Erhalt der Rechnung.</span></p>\r\n<p> </p>\r\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\"><strong>Bemerkungen</strong></span></p>\r\n<p><span style=\"font-size: 10pt; font-family: arial, helvetica, sans-serif;\"><span class=\"mceNonEditable\">[[invoice.remark]]</span></span></p>\r\n<div class=\"footer\">\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 10pt;\">Wie hoffen, Sie hatten einen angenehmen Aufenthalt. Bitte denken Sie gerne an die Tage in unserem Haus zurück. Auf Wiedersehen!<br><br></span></p>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 49.6849%; vertical-align: top;\"><span style=\"font-size: 8pt; font-family: arial, helvetica, sans-serif; color: #7e8c8d;\">Bankverbindung:</span><br><span style=\"font-size: 8pt; font-family: arial, helvetica, sans-serif; color: #7e8c8d;\">Bank AG</span><br><span style=\"font-size: 8pt; font-family: arial, helvetica, sans-serif; color: #7e8c8d;\">IBAN: DE12 3456 7890 1234 5678 90</span><br><span style=\"font-size: 8pt; font-family: arial, helvetica, sans-serif; color: #7e8c8d;\">BIC: XXXXXXXXX </span></td>\r\n<td style=\"width: 49.6849%; text-align: right; vertical-align: top;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt; color: #7e8c8d;\">Steuernummer: 123/456/78901</span><br><br><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt; color: #7e8c8d;\">eMail: info@meinhotel.tld</span><br><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt; color: #7e8c8d;\">www.meinhotel.tld</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>','{\"orientation\": \"P\", \"marginLeft\": 25, \"marginRight\": 20, \"marginTop\": 20, \"marginBottom\": 20, \"marginHeader\": 9, \"marginFooter\": 9}',1,NULL,NULL),(3,'PDF Vorlage für Reservierungen','<!DOCTYPE html>\n<html>\n<head>\n<style type=\"text/css\">\ntable th {\n    padding: 8px 2px 8px 2px;\n}\ntable td {\n    padding: 4px;\n}\n</style>\n</head>\n<body>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\">Mein Hotel</span><br /><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\">Hotelstraße 1</span><br /><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\">123456 Hotelhausen</span></p>\n<p> </p>\n<p><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\">[[reservation1.booker.salutation]] <span class=\"mceNonEditable\">[[reservation1.booker.firstname]] </span><span class=\"mceNonEditable\">[[reservation1.booker.lastname]]<br /><span class=\"mceNonEditable\">[[address.address]]<br /><span class=\"mceNonEditable\">[[address.zip]] <span class=\"mceNonEditable\">[[address.city]]</span></span></span></span></span></p>\n<p> </p>\n<p> </p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\"><strong>Reserverierungsbestätigung</strong></span></p>\n<table border=\"0\">\n<tbody>\n<tr>\n<th style=\"text-align: left;\"><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Von</span></th>\n<th style=\"text-align: left;\"><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Bis</span></th>\n<th style=\"text-align: left;\"><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Zimmer</span></th>\n<th style=\"text-align: left;\"><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Personen</span></th>\n<th style=\"text-align: left;\"><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Preis</span></th>\n</tr>\n<!-- [% for position in apartmentPositions %] -->\n<tr>\n<td><span class=\"mceNonEditable\" style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">[[position.startDate|date(\'d.m.Y\')]]</span></td>\n<td><span class=\"mceNonEditable\" style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">[[position.endDate|date(\'d.m.Y\')]]</span></td>\n<td><span class=\"mceNonEditable\" style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">[[position.description]]</span></td>\n<td><span class=\"mceNonEditable\" style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">[[position.persons]]</span></td>\n<td><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">[[position.totalPrice]] €</span></td>\n</tr>\n<!-- [% endfor %] --></tbody>\n</table>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\"><!-- [% for position in miscPositions %] --><span class=\"mceNonEditable\">[[position.description]]</span>: <span class=\"mceNonEditable\">[[position.totalPrice]]</span> €<br /><!-- [% endfor %] --></span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\"><strong>Gesamt: <span class=\"mceNonEditable\">[[totalPrice]]</span> €<br /></strong></span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 11pt;\">Sehr geehrte/r <span class=\"mceNonEditable\">[[reservation1.booker.salutation]] <span class=\"mceNonEditable\">[[reservation1.booker.lastname]],</span></span></span></p>\n<p><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">gerne bestätigen wir Ihnen hiermit oben genannte Zimmerreservierung.</span><br /><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Der Preis pro Zimmer / Übernachtung beinhaltet Frühstücksbüfett, Service und Mehrwertsteuer.</span></p>\n<p> </p>\n<p><span style=\"font-size: 11pt; font-family: arial, helvetica, sans-serif;\">Mit freundlichen Grüßen</span></p>\n<p> </p>\n</body>\n</html>','{\"orientation\": \"P\", \"marginLeft\": 25, \"marginRight\": 20, \"marginTop\": 20, \"marginBottom\": 20, \"marginHeader\": 9, \"marginFooter\": 9}',1,NULL,NULL),(4,'PDF Kassenblatt','<!DOCTYPE html>\n<html>\n<head>\n<style type=\"text/css\">\ntable th {\n    padding: 8px 2px 8px 2px;\n}\ntable td {\n    padding: 4px;\n}\n</style>\n</head>\n<body>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 18pt;\"><strong>Kassenblatt <span class=\"mceNonEditable\">[[getLocalizedMonth(journal.cashMonth, \'MMMM\', app.request.locale)]] <span class=\"mceNonEditable\">[[journal.cashYear]]</span></span></strong></span></p>\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"0\" cellspacing=\"0px\">\n<tbody>\n<tr>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">#</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Einnahmen</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Ausgaben</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Bestand €</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Gegenkto.</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Rg.Nr.</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Bel.Nr.</span></th>\n<th style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Datum</span></th>\n<th style=\"border-bottom: 1px solid #333333;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">Bemerkung</span></th>\n</tr>\n<!-- [% for entry in journal.cashJournalEntries %] -->\n<tr>\n<td style=\"border-right: 1px solid #dddddd; border-bottom: 1px solid #dddddd; text-align: center;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[loop.index]]</span></td>\n<td style=\"border-right: 1px solid #dddddd; border-bottom: 1px solid #dddddd; text-align: right;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.incomesF]]</span></td>\n<td style=\"border-right: 1px solid #dddddd; border-bottom: 1px solid #dddddd; text-align: right;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.expensesF]]</span></td>\n<td style=\"border-right: 1px solid #dddddd; border-bottom: 1px solid #dddddd; text-align: right;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.inventoryF]]</span></td>\n<td style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.counterAccount]]</span></td>\n<td style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.invoiceNumber]]</span></td>\n<td style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.documentNumberF]]</span></td>\n<td style=\"border-right: 1px solid #DDDDDD; border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.date|date(\'d.m.Y\')]]</span></td>\n<td style=\"border-bottom: 1px solid #DDDDDD;\"><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif; font-size: 8pt;\">[[entry.remark]]</span></td>\n</tr>\n<!-- [% endfor %] --></tbody>\n</table>\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"0\">\n<tbody>\n<tr>\n<td style=\"width: 80.4191%; text-align: right;\"><span style=\"color: #555555; font-size: 9pt;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">Bestand Anfang:</span></strong></span></td>\n<td style=\"width: 19.5809%; text-align: right;\"><span style=\"color: #555555; font-size: 9pt;\"><strong><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif;\">[[journal.cashStartF]] €</span></strong></span></td>\n</tr>\n<tr>\n<td style=\"width: 80.4191%; text-align: right;\"><span style=\"color: #555555; font-size: 9pt;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">Bestand Ende:</span></strong></span></td>\n<td style=\"width: 19.5809%; text-align: right;\"><span style=\"color: #555555; font-size: 9pt;\"><strong><span class=\"mceNonEditable\" style=\"font-family: arial, helvetica, sans-serif;\">[[journal.cashEndF]] €</span></strong></span></td>\n</tr>\n</tbody>\n</table>\n<pagefooter name=\"footer\" content-right=\"{PAGENO}/{nbpg}\"></pagefooter><setpagefooter name=\"footer\" value=\"on\"></setpagefooter>\n</body>\n</html>','{\"orientation\": \"P\", \"marginLeft\": 25, \"marginRight\": 20, \"marginTop\": 20, \"marginBottom\": 20, \"marginHeader\": 9, \"marginFooter\": 9}',1,NULL,NULL),(5,'PDF für DSGVO Export','<style type=\"text/css\">\r\n.general {\r\n    border-collapse: collapse;\r\n    border: 0;\r\n    border-spacing: 0;\r\n    width: 100%;\r\n}\r\n\r\n.general td {\r\n    padding: 4px;\r\n    vertical-align: top;\r\n}\r\n\r\n.general .first {\r\n    width: 25%;\r\n}\r\n\r\nh1 {\r\n    margin: 0;\r\n    color: #333333;\r\n}\r\n</style>\r\n<h1>Allgemein</h1>\r\n<table class=\"general\">\r\n<tbody>\r\n<tr>\r\n<td class=\"first\">Name:</td>\r\n<td>[[ customer.salutation ]] [[ customer.firstname ]] [[ customer.lastname ]]</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">Geburtsdatum:</td>\r\n<td>{% if customer.birthday %} [[ customer.birthday|date(\'d.m.Y\') ]] {% endif %}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">Bemerkung:</td>\r\n<td>[[ customer.remarkF ]]</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h1>Adressen</h1>\r\n<!-- [% for address in customer.customerAddresses %] -->\r\n<h6 class=\"panel-title\">[[ \'customer.contact\'|trans ]] ([[ address.type|trans ]])</h6>\r\n<table class=\"general\">{% if address.company %}\r\n<tbody>\r\n<tr>\r\n<td class=\"first\">[[ \'customer.company\'|trans ]]:</td>\r\n<td>[[ address.company ]]</td>\r\n</tr>\r\n{% endif %}\r\n<tr>\r\n<td class=\"first\">[[ \'reservation.preview.customer.address\'|trans ]]:</td>\r\n<td>[[ address.address ]]<br>[[ address.zip ]] [[ address.city ]]<br>[[ address.country ]]</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">[[ \'customer.email\'|trans ]]:</td>\r\n<td>{% if address.email %}[[ address.email ]]{% else %} -{% endif %}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">[[ \'customer.phone\'|trans ]]:</td>\r\n<td>{% if address.phone %}[[ address.phone ]]{% else %} -{% endif %}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">[[ \'customer.fax\'|trans ]]:</td>\r\n<td>{% if address.fax %}[[ address.fax ]]{% else %} -{% endif %}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">[[ \'customer.mobilephone\'|trans ]]:</td>\r\n<td>{% if address.mobilephone %}[[ address.mobilephone ]]{% else %} -{% endif %}</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<!-- [% endfor %] -->\r\n<h1>Übernachtungen</h1>\r\n<!-- [% for reservation in customer.reservations %] -->\r\n<h6>[[ reservation.startDate|date(\'d.m.Y\') ]] - [[ reservation.endDate|date(\'d.m.Y\') ]] ([[ reservation.appartement.description ]])</h6>\r\n<table class=\"general\">\r\n<tbody>\r\n<tr>\r\n<td class=\"first\">Gebucht über:</td>\r\n<td>[[ reservation.reservationOrigin.name ]]</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">Anzahl Personen:</td>\r\n<td>[[ reservation.persons ]]</td>\r\n</tr>\r\n<tr>\r\n<td class=\"first\">Rechnungen:</td>\r\n<td><!-- [% for invoice in reservation.invoices %] -->[[ invoice.number ]] ([[ invoice.date|date(\'d.m.Y\') ]]){%if not loop.last %}, {% endif %}<!-- [% endfor %] --></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<!-- [% endfor %] -->','{\"orientation\": \"P\", \"marginLeft\": 25, \"marginRight\": 20, \"marginTop\": 20, \"marginBottom\": 20, \"marginHeader\": 9, \"marginFooter\": 9}',1,NULL,NULL);
