  `charge` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loading_equipment` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confirmation_state` int(11) NOT NULL DEFAULT 0,
  `tr_username` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tr_computer_ip` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tr_blocked` tinyint(1) NOT NULL DEFAULT 0,
  `tr_start_date` datetime DEFAULT NULL,
  `tr_edited` tinyint(1) NOT NULL DEFAULT 0,
  `tr_type` int(11) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
